"use client";

import { AnimatePresence, motion } from "motion/react";
import { useEffect, useRef, useState } from "react";

export function SplitButtonTailwind({ actions = ["Deploy to preview", "Deploy without cache", "Roll back"] }) {
  const [open, setOpen] = useState(false);
  const root = useRef<HTMLDivElement>(null);
  const trigger = useRef<HTMLButtonElement>(null);
  const items = useRef<(HTMLButtonElement | null)[]>([]);
  useEffect(() => {
    if (!open) return;
    items.current[0]?.focus();
    const out = (e: PointerEvent) => !root.current?.contains(e.target as Node) && setOpen(false);
    document.addEventListener("pointerdown", out);
    return () => document.removeEventListener("pointerdown", out);
  }, [open]);
  const onKey = (e: React.KeyboardEvent) => {
    const i = items.current.indexOf(document.activeElement as HTMLButtonElement);
    if (e.key === "Escape") { setOpen(false); trigger.current?.focus(); }
    if (e.key === "ArrowDown" || e.key === "ArrowUp") { e.preventDefault(); items.current[(i + (e.key === "ArrowDown" ? 1 : -1) + actions.length) % actions.length]?.focus(); }
  };
  return (
    <div ref={root} className="relative inline-flex text-sm font-medium text-white">
      <button type="button" className="h-9 rounded-l-lg bg-indigo-500 px-4 hover:bg-indigo-400">Deploy to production</button>
      <button ref={trigger} type="button" aria-label="More deploy options" aria-haspopup="menu" aria-expanded={open} onClick={() => setOpen(!open)} className="grid h-9 w-8 place-items-center rounded-r-lg border-l border-white/30 bg-indigo-500 hover:bg-indigo-400">
        <svg aria-hidden="true" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className={`transition-transform ${open ? "rotate-180" : ""}`}><path d="m6 9 6 6 6-6" /></svg>
      </button>
      <AnimatePresence>
        {open && (
          <motion.div role="menu" onKeyDown={onKey} initial={{ opacity: 0, scale: 0.95, y: -4 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.97 }} transition={{ duration: 0.16 }} className="absolute right-0 top-full z-50 mt-1.5 min-w-52 origin-top-right rounded-xl border border-zinc-800 bg-zinc-900 p-1 text-zinc-100 shadow-xl">
            {actions.map((a, i) => (
              <button key={a} ref={(el) => { items.current[i] = el; }} role="menuitem" tabIndex={-1} type="button" onClick={() => { setOpen(false); trigger.current?.focus(); }} className="flex h-8 w-full items-center rounded-md px-2.5 text-left outline-none hover:bg-zinc-800 focus:bg-zinc-800">{a}</button>
            ))}
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
